{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Asciminib, the closest analogue (Morgan 0.3085), shares the amide-pyridine-morpholine and haloalkoxy-aryl framework and has a measured absolute oral bioavailability of ~73% in humans, directly supporting F >= 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Esaxerenone, which shares the methylbenzamide biaryl scaffold, has an absolute oral bioavailability of ~89% in healthy subjects, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Leflunomide, sharing an amide and trifluoromethylated aryl motif, reaches up to 80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Netupitant, containing amide/piperazine and CF3-aryl features, has a high absolute bioavailability of 63-87% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Conivaptan, sharing amide/biphenyl features, has 44% absolute oral bioavailability in humans, still above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "ABT-384 has a model-estimated bioavailability of 18.1% in healthy adults, just below the threshold, but its low Morgan similarity and different scaffold limit transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C13"],
      "claim": "Lisofylline has only 5.9% oral bioavailability in humans, but it is structurally distant from the query and carries low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of transferable experimental evidence from structurally related molecules—asciminib (~73%), esaxerenone (~89-90%), leflunomide (~80%), netupitant (63-87%), and conivaptan (44%)—supports high absolute oral bioavailability (F >= 20%). The low-F analogues are structurally distant and less transferable; the physicochemical low-F prior is uncertain and is overridden by direct human F measurements in closer analogues.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule.",
    "Morgan similarities are modest (max ~0.31), limiting quantitative transferability.",
    "The physicochemical prior suggests solubility-limited absorption, but no experimental solubility or permeability data are available.",
    "Some related drugs (e.g., sorafenib) show formulation/food-dependent bioavailability, so formulation effects for the query are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

